<div class="intro-line"><p>Daftar modul yang dapat diberi izin kepada setiap peran. Perubahan izin dilakukan pada halaman peran.</p><div class="page-actions"><a class="button button-quiet" href="<?= site_url('admin/peran') ?>">Peran & izin</a><a class="button button-dark" href="<?= site_url('admin/modul-akses/tambah') ?>">+ Tambah modul</a></div></div><section class="panel table-panel"><form class="filterbar" method="get" action="<?= site_url($path) ?>"><label class="search-field"><span>Cari modul</span><input type="search" name="q" value="<?= h($p['q']) ?>" placeholder="Kode atau nama"></label><label><span>Status</span><select name="status"><option value="">Semua</option><option value="aktif" <?= $p['status']==='aktif'?'selected':'' ?>>Aktif</option><option value="arsip" <?= $p['status']==='arsip'?'selected':'' ?>>Nonaktif</option></select></label><label><span>Per halaman</span><select name="per_page"><?php foreach (array(10,25,50,100) as $n): ?><option value="<?= $n ?>" <?= $p['per_page']===$n?'selected':'' ?>><?= $n ?></option><?php endforeach; ?></select></label><button class="button button-dark button-small">Terapkan</button><a class="button button-quiet button-small" href="<?= site_url($path) ?>">Reset</a></form><div class="table-wrap"><table><thead><tr><th>Kode</th><th>Nama modul</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach ($rows as $r): ?><tr><td class="mono"><?= h($r['code']) ?></td><td><strong><?= h($r['name']) ?></strong></td><td><span class="pill <?= $r['active']?'pill-green':'pill-muted' ?>"><?= $r['active']?'Aktif':'Nonaktif' ?></span></td><td><a class="row-link" href="<?= site_url('admin/modul-akses/'.$r['id'].'/ubah') ?>">Ubah →</a></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="4" class="empty-cell">Tidak ada modul yang sesuai.</td></tr><?php endif; ?></tbody></table></div><?php $this->load->view('partials/pagination'); ?></section>
